create table RB_CONTACT_LIST (INTERNAL_KEY INT not null  ,DOCUMENT_ID VARCHAR(40) null  ,DOCUMENT_TYPE VARCHAR(6) null  ,LINKMAN_TYPE VARCHAR(2) not null  ,LINKMAN_NAME VARCHAR(100) null  ,PHONE_NO1 VARCHAR(30) not null  ,PHONE_NO2 VARCHAR(30) null  ,CONTACT_STATUS VARCHAR(1) null  ,CONTACT_CLASS VARCHAR(1) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,LAST_CHANGE_USER_ID VARCHAR(30) null  ,CLIENT_NO VARCHAR(22) not null  ,LINKMAN_DESC VARCHAR(50) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CHECK_CERTIFICATE_FLAG VARCHAR(1) null  ,CHECK_CERTIFICATE_ORDER VARCHAR(1) null  ,CONTACT_TYPE VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(INTERNAL_KEY,LINKMAN_TYPE,PHONE_NO1,CLIENT_NO));